// Extract text from Claude response
const content = $json.content;
if (!content || !content[0] || content[0].type !== 'text') {
  throw new Error('Unexpected Claude API response format: ' + JSON.stringify($json).substring(0, 300));
}

let rawText = content[0].text.trim();

// Strip markdown code fences if Claude added them despite instructions
if (rawText.startsWith('```')) {
  rawText = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
}

let fields;
try {
  fields = JSON.parse(rawText);
} catch (e) {
  throw new Error('JSON parse failed. Claude returned: ' + rawText.substring(0, 500));
}

// Calculate down_payment_pct if missing
if (fields.cash_at_closing && fields.sales_price && !fields.down_payment_pct) {
  fields.down_payment_pct = parseFloat(((fields.cash_at_closing / fields.sales_price) * 100).toFixed(1));
}

// Calculate estimated_ltv if missing
if (fields.loan_amount && fields.sales_price && !fields.estimated_ltv) {
  fields.estimated_ltv = parseFloat(((fields.loan_amount / fields.sales_price) * 100).toFixed(1));
}

// Calculate option_expiration if missing
if (fields.effective_date && fields.option_period_days && !fields.option_expiration) {
  const d = new Date(fields.effective_date + 'T00:00:00');
  d.setDate(d.getDate() + parseInt(fields.option_period_days));
  fields.option_expiration = d.toISOString().split('T')[0];
}

// Carry forward webhook metadata
const webhook = $('Webhook').first().json;
fields._document_id = webhook.document_id;
fields._loan_id = webhook.loan_id;
fields._user_id = webhook.user_id;
fields._file_name = webhook.file_name;

return [{ json: fields }];

